import React, { useState } from "react";

export default function FarmerLogin() {
  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!phone || !password) {
      alert("Please fill all fields");
      return;
    }

    if (phone.length !== 10) {
      alert("Enter valid 10-digit phone number");
      return;
    }

    alert("Farmer Login Successful! (Demo)");
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-r from-green-100 to-emerald-200">
      <div className="bg-white shadow-xl rounded-2xl p-8 w-full max-w-md">
        <h2 className="text-3xl font-bold text-center text-green-700 mb-6">
          Farmer Login
        </h2>

        <form onSubmit={handleSubmit} className="space-y-5">
          {/* Phone */}
          <div>
            <label className="block text-gray-600 mb-1">Phone Number</label>
            <input
              type="tel"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              placeholder="Enter phone number"
              maxLength="10"
              className="w-full px-4 py-2 border rounded-xl focus:outline-none focus:ring-2 focus:ring-green-400"
            />
          </div>

          {/* Password */}
          <div>
            <label className="block text-gray-600 mb-1">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter password"
              className="w-full px-4 py-2 border rounded-xl focus:outline-none focus:ring-2 focus:ring-green-400"
            />
          </div>

          {/* Button */}
          <button
            type="submit"
            className="w-full bg-green-600 text-white py-2 rounded-xl font-semibold hover:bg-green-700 transition duration-300"
          >
            Login
          </button>
        </form>

        {/* Extra Links */}
        <div className="text-center mt-5 text-sm text-gray-600">
          <p className="cursor-pointer hover:text-green-600">Forgot Password?</p>
          <p className="mt-2">
            New Farmer?{" "}
            <span className="text-green-600 font-semibold cursor-pointer hover:underline">
              Register Here
            </span>
          </p>
        </div>
      </div>
    </div>
  );
}
